import * as React from "react"
import { cn } from "@/lib/utils"

export type MessageProps = {
  children: React.ReactNode
  className?: string
} & React.HTMLProps<HTMLDivElement>

function Message({ children, className, ...props }: MessageProps) {
  return <div data-slot="message" className={cn("message flex gap-3", className)} {...props}>{children}</div>
}

export type MessageContentProps = {
  children: React.ReactNode
  className?: string
} & React.HTMLProps<HTMLDivElement>

function MessageContent({ children, className, ...props }: MessageContentProps) {
  return (
    <div
      data-slot="message-content"
      className={cn("message-content break-words whitespace-normal", className)}
      {...props}
    >
      {children}
    </div>
  )
}

export { Message, MessageContent }
